static int checks=0;
void check(bool value,const char*message){require(value,message);checks++;}
template<class F>void rejects(F fn,const char*message){bool failed=false;try{fn();}catch(const std::exception&){failed=true;}check(failed,message);}
Frame frame(uint64_t slot,bool failed=false,size_t logs=0){geyser::SubscribeUpdate u;auto*t=u.mutable_transaction();t->set_slot(slot);t->set_bank_id(123);auto*info=t->mutable_transaction();info->set_signature(std::string(64,char(slot)));auto*m=info->mutable_meta();if(failed)m->mutable_err()->set_err("failure");if(logs)m->add_log_messages(std::string(logs,'A'));auto raw=u.SerializeAsString();raw.append("\xa0\x9c\x01\x01",4);auto c=inspect(u,raw);return {raw,wall_ns(),c};}
std::string bytes(const fs::path&p){std::ifstream f(p,std::ios::binary);return std::string(std::istreambuf_iterator<char>(f),{});}
void put(const fs::path&p,const std::string&s){std::ofstream f(p,std::ios::binary|std::ios::trunc);f.write(s.data(),s.size());}
int main(int argc,char**argv){try{require(argc==2,"isolated test output required");fs::path root=argv[1];require(!fs::exists(root),"test directory must be new");fs::create_directories(root);auto started=mono_ns();std::vector<Frame>input;for(int i=0;i<1200;i++)input.push_back(frame(100+i,i%3==0,400));
 {Store s(root/"roundtrip",0,8192);for(size_t i=0;i<input.size();i+=8)s.append(std::vector<Frame>(input.begin()+i,input.begin()+i+8));s.finish();check(s.snapshot()["retained"]==input.size(),"retained count");check(s.snapshot()["failed"]==400,"failed originals retained");}
 size_t cursor=0;std::vector<fs::path>paths;for(auto&e:fs::directory_iterator(root/"roundtrip/originals"))if(e.is_directory())paths.push_back(e.path());std::sort(paths.begin(),paths.end());for(auto&p:paths)scan(p/"inputs.sli",[&](Frame&&f){check(f.raw==input.at(cursor).raw,"wire bytes including unknown fields differ");check(f.stamp==input.at(cursor).stamp,"ingress stamp differs");cursor++;});check(cursor==input.size(),"all originals replayed");
 {Store s(root/"roundtrip",0,8192);check(s.snapshot()["retained"]==1200,"restart counters");check(s.snapshot()["failed"]==400,"restart failed counters");s.append({input.front(),input.front()});check(s.snapshot()["retained"]==1202,"duplicates retained for downstream identity logic");rejects([&]{Store second(root/"roundtrip",0);},"single writer lock");}
 auto source=root/"roundtrip/originals/00000001/inputs.sli";auto original=bytes(source);
 for(int kind=0;kind<5;kind++){auto p=root/("corrupt-"+std::to_string(kind));fs::create_directories(p/"originals/00000001");auto target=p/"originals/00000001/inputs.sli";auto damaged=original;if(kind==0)damaged.resize(10);if(kind==1)damaged.pop_back();if(kind==2)damaged[24]^=1;if(kind==3)damaged[8]=9;if(kind==4)damaged[0]='X';put(target,damaged);rejects([&]{Store s(p,0);},"corrupt original accepted");check(bytes(target)==damaged,"corruption silently truncated");}
 {Store s(root/"reserve",UINT64_MAX);rejects([&]{s.append({input.front()});},"reserve overflow admitted");check(!fs::exists(root/"reserve/durable-tail.json"),"failed write advanced tail");}
 {Store s(root/"marker",0);s.append({input.front()});auto head=read_json(root/"marker/durable-tail.json");check(head["records"]==1,"published marker count");check(head["offset"]==fs::file_size(root/"marker/originals/00000001/inputs.sli"),"published exact durable end");}
 fs::remove(root/"marker/durable-tail.json");{Store s(root/"marker",0);check(read_json(root/"marker/durable-tail.json")["records"]==1,"lost marker reconstruction");}
 {Store s(root/"gaps",0);s.gap(100,200,"response");s.gap(150,250,"response2");check(s.snapshot()["unrepairedGapWitnesses"]==2,"gap journal progression");rejects([&]{s.gap(200,100,"");},"invalid gap admitted");}
 {Store s(root/"gaps",0);check(s.snapshot()["unrepairedGapWitnesses"]==2,"gap journal survives missing telemetry");}
 {FrameQueue q;std::atomic<bool>ordered{true};std::thread consumer([&]{std::vector<Frame>b;size_t seen=0;while(q.take(b)){for(auto&f:b)if(f.counts.last!=100+seen++)ordered=false;q.commit(b.size());b.clear();}if(seen!=10000)ordered=false;});for(size_t i=0;i<10000;i++)q.push(frame(100+i));q.drain();q.close();consumer.join();auto status=q.status();check(ordered,"concurrent queue ordering");check(status["committedThisRun"]==10000,"concurrent exact delivery");check(status["pendingFrames"]==0,"queue drained");check(status["peakBytes"].get<uint64_t>()<=queue_bytes,"queue byte bound");}
 {FrameQueue q;for(int i=0;i<256;i++)check(q.push(frame(i+100)),"queue fill");std::atomic<bool>released{false};std::thread producer([&]{released=!q.push(frame(1000));});std::this_thread::sleep_for(std::chrono::milliseconds(10));q.close();producer.join();check(released,"blocked producer cancellation");}
 int pipefd[2];require(pipe(pipefd)==0,"test pipe");auto child=fork();require(child>=0,"test fork");if(child==0){close(pipefd[0]);try{Store s(root/"crash",0);s.append({input.front()});char ready=1;if(write(pipefd[1],&ready,1)!=1)_exit(4);for(;;)pause();}catch(...){_exit(3);}}close(pipefd[1]);char ready=0;check(read(pipefd[0],&ready,1)==1,"child durable commit");close(pipefd[0]);kill(child,SIGKILL);int status=0;waitpid(child,&status,0);{Store s(root/"crash",0);check(s.snapshot()["retained"]==1,"SIGKILL committed original restart");s.append({input.at(1)});check(s.snapshot()["retained"]==2,"SIGKILL resume append");}
 auto result=Json{{"passed",true},{"assertions",checks},{"originalFrames",input.size()},{"concurrentFrames",10000},{"elapsedMs",(mono_ns()-started)/1e6},{"scope","bounded wire compatibility, integrity, crash and concurrent queue cases; not exhaustive proof"}};atomic_json(root/"report.json",result,true);std::cout<<result.dump()<<'\n';return 0;
 }catch(const std::exception&e){std::cerr<<"native checks failed: "<<e.what()<<'\n';return 1;}}
